import { cn } from "@/lib/utils";
import { KbdShortcuts } from "@/registry/new-york/kbd-shortcuts/KbdShortcuts";

export const menuShortcutKeys = (shortcut: string | string[]) => {
  if (Array.isArray(shortcut)) {
    return shortcut;
  }
  return (
    shortcut.includes("+")
      ? shortcut.split("+")
      : (shortcut.match(/[⌘⌥⇧⌃↵⌫⎋]|[^⌘⌥⇧⌃↵⌫⎋]+/gu) ?? [])
  )
    .map((key) => key.trim())
    .filter(Boolean);
};

export const MenuShortcut = ({
  shortcut,
  destructive,
  className,
}: {
  shortcut: string | string[];
  destructive?: boolean | undefined;
  className?: string | undefined;
}) => (
  <KbdShortcuts
    shortcuts={menuShortcutKeys(shortcut)}
    separator={null}
    classNames={{
      key: "h-6 min-w-6 justify-center border-current/20 bg-transparent px-1.5 text-sm text-current",
      root: cn(
        "ml-auto shrink-0 gap-1",
        destructive ? "text-current" : "text-muted-foreground",
        className
      ),
    }}
  />
);

import * as React from "react";

import type { ReactFC } from "@/lib/types";
import { cn } from "@/lib/utils";
import type { KbdClassNames } from "@/registry/new-york/kbd/Kbd";
import { Kbd } from "@/registry/new-york/kbd/Kbd";

export interface KbdShortcutsProps {
  shortcuts: string[];
  separator?: string | null | undefined;
  classNames?: KbdClassNames | undefined;
}
export const KbdShortcuts: ReactFC<KbdShortcutsProps> = ({
  shortcuts,
  separator = "+",
  classNames,
}) => (
  <div className={cn("flex items-center gap-1.5", classNames?.root)}>
    {shortcuts.map((shortcut: string, index: number) => (
      <React.Fragment key={`${shortcut}-${index}`}>
        <Kbd
          keys={[shortcut]}
          classNames={{
            key: classNames?.key,
            root: "",
            separator: classNames?.separator,
          }}
        />
        {separator !== null && index !== shortcuts.length - 1 && (
          <span
            className={cn(
              "text-muted-foreground text-xs",
              classNames?.separator
            )}
          >
            {separator}
          </span>
        )}
      </React.Fragment>
    ))}
  </div>
);

import type { LucideIcon } from "lucide-react";
import type { PropsWithChildren } from "react";

export type ReactFC<T> = React.FC<PropsWithChildren & T>;
export type Size = "xs" | "sm" | "md" | "lg" | "xl";
export interface SelectOption {
  value: string;
  label?: string | undefined;
  emoji?: string | undefined;
  icon?: LucideIcon | undefined;
  closeOnClick?: boolean | undefined;
  disabled?: boolean | undefined;
}
